def _control():
    try:
        from simulations.stripe.control import get_control

        return get_control()
    except Exception:
        return None


def _record(kind: str, payload: dict) -> dict:
    control = _control()
    row = {"kind": kind, **payload}
    if control is not None:
        control.record(row)
    return row


def _cash_agent_record(trace, *, llm_called: bool, decision_fn_name: str, agent_invoked: bool) -> dict:
    facts = trace.facts
    tools = ["get_cash_application_facts"]
    if facts and facts.identified_customer_id:
        tools.append("get_ar_customer")
        if facts.precedents:
            tools.append("get_ar_precedents")
    agents = ["Cash Application Agent"]
    skills = ["cash-application"]
    if trace.reviewer is not None:
        agents.append("Cash Application Reviewer")
    validations = ["validate_proposal"]
    if trace.reviewer is not None:
        validations.append("needs_reviewer")
    if trace.posted:
        validations.append("post_application_balanced_journal")
    return _record(
        "cash_apply",
        {
            "agent_invoked": agent_invoked,
            "agents": agents,
            "decision_requested": "Choose AUTO_APPLY, HUMAN_REVIEW, or UNAPPLIED among Python candidates.",
            "evidence": list(facts.facts) if facts else [],
            "candidates": [
                {
                    "candidate_id": item.candidate_id,
                    "match_type": item.match_type,
                    "invoice_ids": [row.invoice_id for row in item.applications],
                }
                for item in (facts.candidates if facts else [])
            ],
            "skills": skills,
            "tools_called": tools,
            "llm_called": llm_called,
            "decision_fn": decision_fn_name,
            "final_decision": trace.final.decision if trace.final else None,
            "reason": trace.final.reason if trace.final else "",
            "validations": validations,
            "validation_passed": bool(trace.validation.passed) if trace.validation else False,
            "downstream": {
                "posted": trace.posted,
                "invoice_ids": [item.invoice_id for item in (trace.final.applications if trace.final else [])],
                "precedent_used": list(trace.final.precedent_used) if trace.final else [],
                "precedent_affected": bool(trace.final.precedent_affected) if trace.final else False,
            },
        },
    )


def _iso_date(value) -> str:
    if isinstance(value, int):
        return datetime.fromtimestamp(value, tz=timezone.utc).date().isoformat()
    text = str(value or "")
    if len(text) >= 10 and text[4] == "-":
        return text[:10]
    return datetime.now(timezone.utc).date().isoformat()


def _metadata(obj: dict) -> dict:
    raw = obj.get("metadata") if isinstance(obj.get("metadata"), dict) else {}
    return {str(key): str(value) for key, value in raw.items() if value not in (None, "")}


def _invoice_hint(obj: dict) -> str | None:
    meta = _metadata(obj)
    for key in ("invoice_id", "order_id", "internal_invoice_id"):
        value = meta.get(key)
        if value:
            return value
    invoice = obj.get("invoice")
    if isinstance(invoice, str) and invoice.upper().startswith("INV"):
        return invoice
    return None


def _payer_name(obj: dict) -> str:
    billing = obj.get("billing_details") if isinstance(obj.get("billing_details"), dict) else {}
    if billing.get("name"):
        return str(billing["name"])
    customer = obj.get("customer")
    if isinstance(customer, dict) and customer.get("name"):
        return str(customer["name"])
    meta = _metadata(obj)
    if meta.get("customer_name"):
        return meta["customer_name"]
    if obj.get("description"):
        return str(obj["description"])
    return ""



